static const char* autoMonitorPage = R"MONITOR(<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Auto Monitor · SDR-Tiouner</title>
<style>
:root{color-scheme:dark;font-family:system-ui,sans-serif;background:#080e18;color:#e5edf8}body{margin:0}header,main{max-width:1480px;margin:auto;padding:20px}header{display:flex;gap:28px;align-items:center;border-bottom:1px solid #27354a;padding-top:12px;padding-bottom:12px}.brand{display:flex;align-items:center;gap:9px;white-space:nowrap;font-size:18px;font-weight:700}.brand img{width:32px;height:32px;border-radius:8px;object-fit:cover}.page-nav{display:flex;align-items:center;gap:20px}.page-title{display:flex;align-items:center;gap:8px;font-size:18px;font-weight:650;white-space:nowrap;color:#e5edf8}.page-nav a{display:flex;align-items:center;gap:8px;padding:8px 14px;border-radius:6px;text-decoration:none;font-size:14px;white-space:nowrap;color:#a9bbd3;background:#111c2c;border:1px solid #3a4d66}.page-nav a:hover{color:#e5edf8;background:#1a2940}.page-nav a[aria-current="page"]{background:#263e5e;color:#fff;font-weight:600}.experimental{font-size:10px;font-weight:500;color:#a9bbd3;border:1px solid #506887;border-radius:4px;padding:2px 5px}.layout-label{display:flex;align-items:center;gap:8px;white-space:nowrap;font-size:13px;color:#a9bbd3;margin-left:auto}a{color:#a9c7ff}button,select{background:#1a2940;color:inherit;border:1px solid #456083;border-radius:7px;padding:10px;cursor:pointer}button:disabled{opacity:.5;cursor:default}.controls{display:flex;gap:12px;align-items:center;flex-wrap:wrap}.info{color:#a9bbd3;font-size:14px;line-height:1.7}#status{padding:16px 0;color:#8de0bc}#error{color:#ffa998}#grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}article{background:#111c2c;border:1px solid #2c405b;border-radius:10px;overflow:hidden}.picture{position:relative;background:#000;aspect-ratio:16/9}video{width:100%;height:100%;object-fit:contain}.empty{position:absolute;inset:0;display:grid;place-items:center;color:#8b9cb2;pointer-events:none}.meta{display:grid;grid-template-columns:minmax(0,1fr) auto minmax(0,1fr);align-items:center;gap:8px;padding:6px 12px;min-height:24px}.station{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:14px}.rate{color:#a9bbd3;font-size:12px;margin-left:5px}.volume{justify-self:end;width:96px;max-width:100%;margin:0;accent-color:#2789ff;cursor:pointer}.badge{color:#88dab5;font-size:12px}#candidates{margin-top:18px} .spectrum-panel{margin-top:0;border:1px solid #27354a;border-radius:8px;overflow:hidden;background:#0b1421}.spectrum-label{padding:8px 12px;color:#a9bbd3;font-size:12px;display:flex;justify-content:space-between}#activity-spectrum{display:block;width:100%;height:180px;pointer-events:none} @media(max-width:700px){header{flex-wrap:wrap;gap:12px;padding:12px}.brand-text{display:none}.page-nav{gap:12px}.page-title{font-size:15px}.page-nav a{padding:7px 9px;font-size:12px}.experimental{font-size:9px}.layout-label{margin-left:auto}main{padding:12px}.meta{padding:5px;gap:3px}.station{font-size:11px}.rate,.badge{font-size:9px}.volume{width:60px}}
</style></head><body>
<header><span class="brand"><img src="data:image/png;base64," alt="SDR-Tiouner logo"><span class="brand-text">SDR-Tiouner</span></span><nav class="page-nav" aria-label="Receiver pages"><span class="page-title" aria-current="page">Auto Monitor <span class="experimental">experimental</span></span><a href="/receiver">&larr; Receiver</a></nav><label class="layout-label">Layout <select id="layout"><option value="2">2 columns</option><option value="4" selected>4 columns</option></select></label></header>
<main>
<section class="spectrum-panel" aria-label="Read-only BATC Spectrum"><div class="spectrum-label">BATC Spectrum <span id="spectrum-status">Waiting for spectrum</span></div><canvas id="activity-spectrum" role="img" aria-label="Live BATC spectrum from 10490.5 to 10499.5 MHz; display only"></canvas></section>
<div id="status" role="status">Connecting to receiver…</div><div id="error" role="alert"></div><div id="grid"></div><div id="candidates" class="info"></div></main>
<script src="/assets/playback.js"></script>
<script>
const token='__CONTROL_TOKEN__',views=new Map();let state=null,audioId=null,disabledSince=0,nextStart=0;
async function command(action){try{const r=await fetch('/api/auto/'+action,{method:'POST',headers:{'X-OnAir-Control':token}});if(!r.ok)throw Error(await r.text());document.querySelector('#error').textContent='';}catch(e){document.querySelector('#error').textContent=e.message;}}

document.querySelector('#layout').onchange=e=>document.querySelector('#grid').style.gridTemplateColumns='repeat('+e.target.value+',minmax(0,1fr))';
function disconnect(v){v.generation++;if(v.pc)v.pc.close();v.pc=null;v.video.srcObject=null;v.busy=false;if(v.session){fetch(v.session,{method:'DELETE'}).catch(()=>{});v.session=null;}}
async function connect(v){if(!playbackActive||v.pc||v.busy||Date.now()<v.retry)return;v.busy=true;const generation=v.generation,pc=new RTCPeerConnection({bundlePolicy:'max-bundle'});v.pc=pc;const current=()=>playbackActive&&v.generation===generation&&v.pc===pc;
try{pc.addTransceiver('video',{direction:'recvonly'});pc.addTransceiver('audio',{direction:'recvonly'});pc.ontrack=e=>{if(!current())return;const stream=v.video.srcObject||new MediaStream();stream.addTrack(e.track);v.video.srcObject=stream;v.video.play().catch(()=>{});};pc.onconnectionstatechange=()=>{if(current()&&['failed','disconnected','closed'].includes(pc.connectionState)){disconnect(v);v.retry=Date.now()+2000;}};
await pc.setLocalDescription(await pc.createOffer());if(pc.iceGatheringState!=='complete')await new Promise((resolve,reject)=>{const timer=setTimeout(()=>reject(Error('ICE timeout')),3000);pc.onicegatheringstatechange=()=>{if(pc.iceGatheringState==='complete'){clearTimeout(timer);resolve();}};});if(!current())return;
const endpoint=window.location.protocol+'//'+window.location.hostname+':' +v.channel.videoPort+'/onair/whep',r=await fetch(endpoint,{method:'POST',headers:{'Content-Type':'application/sdp'},body:pc.localDescription.sdp,signal:AbortSignal.timeout(4000)});if(r.status!==201)throw Error('Waiting for publisher');const location=r.headers.get('Location'),session=location?new URL(location,endpoint).href:null;if(!current()){if(session)fetch(session,{method:'DELETE'}).catch(()=>{});return;}v.session=session;await pc.setRemoteDescription({type:'answer',sdp:await r.text()});v.videoError='';
}catch(e){if(current()){disconnect(v);v.retry=Date.now()+2000;v.videoError=e.message;v.el.title=e.message;}}finally{if(current())v.busy=false;}}
function makeView(card){const el=document.createElement('article');el.dataset.card=card.uid;el.innerHTML='<div class="picture"><video autoplay muted playsinline></video><div class="empty">Waiting for assignment</div></div><div class="meta"><div class="station"><strong></strong><span class="rate"></span></div><span class="badge"></span><input class="volume" type="range" min="0" max="100" step="1" value="0" aria-label="Audio volume" title="Volume (0 = mute)"></div>';document.querySelector('#grid').append(el);const v={el,video:el.querySelector('video'),pc:null,session:null,generation:0,busy:false,retry:0,revision:-1,channel:null,videoError:''};v.video.volume=0;el.querySelector('.volume').oninput=event=>{const volume=Number(event.target.value)/100;audioId=volume>0?card.uid:null;for(const [id,x]of views){const active=id===audioId;x.video.muted=!active;x.video.volume=active?volume:0;if(!active)x.el.querySelector('.volume').value=0;if(active)x.video.play().catch(()=>{});}};views.set(card.uid,v);return v;}
async function poll(){try{const r=await fetch('/api/state',{signal:AbortSignal.timeout(4000)});if(!r.ok)throw Error('Receiver unavailable');state=await r.json();const a=state.autoMonitor;document.querySelector('#status').textContent=a.message+' · '+(state.batcSpectrum.length?'BATC live':'BATC unavailable')+' · radio '+(state.running?'running':'stopped');
// The monitor starts the radio itself and, while this page is the active one, keeps the scanner running: if it is found
// stopped for 3 s (radio dropout, a manual stop) it is started again, at most every 8 s.
if(a.enabled||!playbackActive)disabledSince=0;else{if(!disabledSince)disabledSince=Date.now();if(Date.now()-disabledSince>=3000&&Date.now()>=nextStart){nextStart=Date.now()+8000;command('start');}}drawActivitySpectrum();
const uids=new Set(a.cards.map(c=>c.uid));for(const [id,v]of views)if(!uids.has(id)){disconnect(v);v.el.remove();views.delete(id);}
for(const card of a.cards){const ch=card.channel?state.channels.find(c=>c.id===card.channel):null,v=views.get(card.uid)||makeView(card);
if(ch){v.channel=ch;if(v.revision!==ch.revision){disconnect(v);v.revision=ch.revision;v.retry=0;}}else{v.channel=null;v.revision=-1;if(v.pc)disconnect(v);}
const name=card.beacon?'Beacon':(ch&&ch.service)||card.frequency.toFixed(3)+' MHz';
v.el.querySelector('strong').textContent=name;v.el.querySelector('.badge').textContent=card.lost?'LOST':!ch||!ch.enabled?'IDLE':ch.locked?'RECEIVING':'ACQUIRING';v.el.querySelector('.rate').textContent=card.symbolRate+' kS/s';
v.el.querySelector('.station').title=name+' · '+card.frequency.toFixed(3)+' MHz · '+card.symbolRate+' kS/s';v.el.querySelector('.volume').setAttribute('aria-label','Volume for '+name);v.el.title=(ch&&ch.error)||v.videoError||'';
const hasPicture=!!ch&&ch.enabled&&v.video.readyState>=2&&v.video.videoWidth>0;v.el.querySelector('.empty').style.display=hasPicture?'none':'grid';
v.el.querySelector('.empty').textContent=card.beacon&&a.beaconMissing?'No beacon received · check the radio-to-LNB connection and LNB bias (18 V)':card.lost?'Signal lost · '+card.frequency.toFixed(3)+' MHz':!ch||!ch.enabled?(card.beacon?'Waiting for beacon':'Waiting for assignment'):ch.locked?'Waiting for video':card.beacon?'Waiting for beacon':'Acquiring transmission…';
if(playbackActive&&state.running&&ch&&ch.enabled&&!ch.error)connect(v);else if(v.pc)disconnect(v);}
document.querySelector('#candidates').textContent='Detected above the beacon: '+(a.candidates.map(c=>c.frequency.toFixed(3)+' MHz / '+c.symbolRate+' kS/s').join(' · ')||'none')+' · '+a.cards.length+' card(s) · estimated symbol rates';
}catch(e){document.querySelector('#status').textContent='Receiver unavailable';document.querySelector('#error').textContent=e.message;}finally{setTimeout(poll,500);}}
const activityCanvas=document.querySelector('#activity-spectrum'),activityContext=activityCanvas.getContext('2d');
function drawActivitySpectrum(){
 const rect=activityCanvas.getBoundingClientRect(),dpr=window.devicePixelRatio||1,w=Math.max(1,rect.width),h=180;
 if(activityCanvas.width!==Math.round(w*dpr)||activityCanvas.height!==Math.round(h*dpr)){activityCanvas.width=Math.round(w*dpr);activityCanvas.height=Math.round(h*dpr);}
 const c=activityContext;c.setTransform(dpr,0,0,dpr,0,0);c.clearRect(0,0,w,h);
 const left=32,right=w-16,top=22,bottom=h-25,x=f=>left+(f-10490.5)/9*(right-left);
 c.font='11px system-ui';c.lineWidth=1;c.textAlign='center';
 for(let row=0;row<5;row++){const y=top+(bottom-top)*row/4;c.strokeStyle='#28394e';c.beginPath();c.moveTo(left,y);c.lineTo(right,y);c.stroke();}
 for(let f=10491;f<=10499;f+=w<600?2:1){c.strokeStyle='#28394e';c.beginPath();c.moveTo(x(f),top);c.lineTo(x(f),bottom);c.stroke();c.fillStyle='#9aafca';c.fillText(f,x(f),h-7);}
 const data=state?.batcSpectrum||[];const floor=.12*65535;let maximum=floor+1;for(const value of data)maximum=Math.max(maximum,value);const span=(maximum-floor)*1.05,spectrumLevel=value=>Math.max(0,Math.min(1,(value-floor)/span));document.querySelector('#spectrum-status').textContent=data.length?'LIVE | MHz':'BATC unavailable · waiting';
 c.save();c.beginPath();c.rect(left,top,right-left,bottom-top);c.clip();
 if(data.length>1){
  // Peak-preserving pixel buckets keep narrow carriers visible without drawing thousands of points.
  const points=[],count=Math.max(1,Math.floor(right-left));
  for(let i=0;i<count;i++){let peak=0;const start=Math.floor(i*data.length/count),end=Math.min(data.length,Math.max(start+1,Math.floor((i+1)*data.length/count)));for(let j=start;j<end;j++)peak=Math.max(peak,data[j]);const level=spectrumLevel(peak);points.push([left+i/(Math.max(1,count-1))*(right-left),bottom-level*(bottom-top)]);}
  c.beginPath();points.forEach((p,i)=>i?c.lineTo(...p):c.moveTo(...p));c.lineTo(right,bottom);c.lineTo(left,bottom);c.closePath();const fill=c.createLinearGradient(0,top,0,bottom);fill.addColorStop(0,'rgba(130,216,178,.5)');fill.addColorStop(1,'rgba(130,216,178,.02)');c.fillStyle=fill;c.fill();c.beginPath();points.forEach((p,i)=>i?c.lineTo(...p):c.moveTo(...p));c.strokeStyle='#82d8b2';c.lineWidth=1.5;c.stroke();
 }else{c.fillStyle='#9aafca';c.fillText('Waiting for BATC spectrum',(left+right)/2,(top+bottom)/2);}
 c.restore();const colors=['#82d8b2','#f0c87a','#99b9ff','#d9a5ee'];
 for(const [i,ch]of (state?.channels||[]).entries())if(ch.enabled&&ch.locked&&ch.service&&data.length>1){
  const bin=Math.round((ch.frequency-10490.5)/9*(data.length-1));if(bin<0||bin>=data.length)continue;
  let sum=0,n=0;for(let j=Math.max(0,bin-3);j<=Math.min(data.length-1,bin+3);j++){sum+=data[j];n++;}
  const level=spectrumLevel(sum/n),label=ch.service;
  const half=Math.min((right-left)/2,c.measureText(label).width/2),px=Math.max(left+half,Math.min(right-half,x(ch.frequency))),py=Math.max(14,bottom-level*(bottom-top)-7);
  c.textAlign='center';c.strokeStyle='#0b1421';c.lineWidth=3;c.strokeText(label,px,py,right-left);c.fillStyle=colors[i%colors.length];c.fillText(label,px,py,right-left);
 }
}
new ResizeObserver(drawActivitySpectrum).observe(activityCanvas);
window.addEventListener('pagehide',()=>{for(const v of views.values())disconnect(v);});poll();
</script></body></html>)MONITOR";
